// ✅ STRUCT: Tiny, Immutable, Stack-allocated
public readonly struct Point 
{
    public int X { get; }
    public int Y { get; }
    public Point(int x, int y) => (X, Y) = (x, y);
}

// ❌ BAD STRUCT: Too big, Heap-allocated fields
public struct BadStruct 
{
    public string Name; // Strings go on the heap anyway!
    public int[] Data;  // Arrays go on the heap!
}

struct Point { public int X; }

// ❌ MODIFIES THE COPY
void Move(Point p) {
    p.X = 99; 
}

// ✅ MODIFIES THE ORIGINAL
void MoveRef(ref Point p) {
    p.X = 99; 
}

Point myPoint = new Point { X = 5 };
Move(myPoint); 
Console.WriteLine(myPoint.X); // Still 5!

MoveRef(ref myPoint);
Console.WriteLine(myPoint.X); // Now 99!

