interface IAnimal { void Speak(); }

struct Dog : IAnimal 
{
    public void Speak() => Console.WriteLine("Woof");
}

Dog myDog = new Dog();
myDog.Speak(); // ✅ Fast! No boxing.

// ❌ AVOID THIS: Casting to interface causes Boxing!
IAnimal boxedDog = myDog; 
boxedDog.Speak(); // Triggers memory allocation on the Heap!

// ✅ ABSTRACT CLASS: Sharing actual code
public abstract class Database 
{
    public void Connect() { Console.WriteLine("Connecting..."); } // Shared
    public abstract void SaveData(); // Must be implemented
}

// ✅ INTERFACE: Sharing a capability
public interface ILoggable 
{
    void LogError(); // No code, just a rule
}

// A class can only have ONE abstract base, but MANY interfaces.
public class SqlDatabase : Database, ILoggable { ... }

// 1. Base Interface
public interface IReader 
{
    void Read();
}

// 2. Derived Interface inherits IReader
public interface IReadWriter : IReader 
{
    void Write();
}

// 3. Class must implement BOTH Read() and Write()
public class FileManager : IReadWriter 
{
    public void Read() { /* ... */ }
    public void Write() { /* ... */ }
}

// ❌ DANGEROUS: If an error happens, the file stays locked forever.
var stream = new FileStream("data.txt", FileMode.Open);
var data = stream.ReadByte();
stream.Dispose(); 

// ✅ SAFE: The 'using' block guarantees Dispose() is called.
using (var stream2 = new FileStream("data.txt", FileMode.Open))
{
    var data2 = stream2.ReadByte();
    // If this throws an error, Dispose() is STILL called!
}

// ✅ MODERN C# (No brackets needed!)
using var stream3 = new FileStream("data.txt", FileMode.Open);
var data3 = stream3.ReadByte();

// ❌ THE LOH KILLER
// Creating massive arrays in a fast loop fragments the LOH rapidly.
for(int i = 0; i < 1000; i++) 
{
    // 100,000 bytes goes straight to the LOH!
    byte[] massiveArray = new byte[100000]; 
}

// ✅ THE FIX (Array Pooling)
// Instead of creating new arrays and throwing them away,
// we check out an array from the library, use it, and return it!
byte[] rented = ArrayPool<byte>.Shared.Rent(100000);
try { /* Use it */ }
finally { ArrayPool<byte>.Shared.Return(rented); }

var numbers = new List<int> { 1, 2, 3 };

// 1. We write the query. NO execution happens here.
var query = numbers.Where(n => n > 2);

// 2. We modify the underlying data BEFORE the query runs!
numbers.Add(5); 

// 3. We execute the query by calling ToList().
// The query runs RIGHT NOW and sees the number '5'!
var result = query.ToList(); 

Console.WriteLine(result.Count); // Outputs 2 (The numbers 3 and 5)

