// ❌ DANGEROUS IN LIBRARIES
public async Task<string> GetDataAsync()
{
    // Captures the UI thread. Can cause deadlocks!
    var data = await _httpClient.GetStringAsync("http://api.com");
    return data.ToUpper(); 
}

// ✅ SAFE FOR LIBRARIES / BACKGROUND WORK
public async Task<string> GetDataSafeAsync()
{
    // Discards the UI thread context. Resumes on a background thread.
    var data = await _httpClient.GetStringAsync("http://api.com").ConfigureAwait(false);
    return data.ToUpper();
}

private readonly object _syncLock = new object();
private readonly SemaphoreSlim _semaphore = new SemaphoreSlim(1, 1);

// ❌ COMPILER ERROR
public async Task DoWorkBadAsync() 
{
    lock (_syncLock) 
    {
        // CS1996: Cannot await in the body of a lock statement
        await Task.Delay(1000); 
    }
}

// ✅ THE SOLUTION: SemaphoreSlim
public async Task DoWorkGoodAsync() 
{
    await _semaphore.WaitAsync(); // Async-friendly lock!
    try 
    {
        await Task.Delay(1000); 
    }
    finally 
    {
        _semaphore.Release();
    }
}

public struct MassiveMathStruct {
    public decimal Val1, Val2, Val3, Val4; // Huge!
}

// ❌ BAD: Copies the entire massive struct into memory
public decimal Calculate(MassiveMathStruct data) {
    return data.Val1 + data.Val2;
}

// ✅ GOOD: Passes a lightweight pointer, but compiler 
// guarantees we can't accidentally modify the data!
public decimal CalculateFast(in MassiveMathStruct data) {
    // data.Val1 = 99; <-- COMPILER ERROR! Read-only!
    return data.Val1 + data.Val2;
}

public class User { public string Name; }

void Modify(User u) 
{
    // 1. Modifying the shared object works!
    u.Name = "Bob"; 

    // 2. Reassigning the pointer ONLY affects this method's copy of the pointer!
    u = new User { Name = "Charlie" };
}

var myUser = new User { Name = "Alice" };
Modify(myUser);

// The Name is Bob! It is NOT Charlie.
Console.WriteLine(myUser.Name);
